body[data-experience='phone'] #stick {
  width: 44px;
  height: 44px;
  left: calc(50% - 22px);
  top: calc(50% - 22px);
}

body[data-experience='phone'] #joystick {
  border-color: #91b1ad;
  border-width: 2px;
  background: radial-gradient(circle at 45% 40%, #42676bba, #132c35bb 73%);
}

body[data-experience='phone'] #joystick {
  border-color: #bdd8cc66;
  border-width: 1px;
  background: #17333226;
  box-shadow: none;
}

body[data-experience='phone'] #stick {
  border: 1px solid #d0e3d57a;
  background: radial-gradient(circle at 35% 30%, #b5d2c36b, #56867c59 73%);
  box-shadow: none;
}

body[data-experience='phone'] #message {
  /* Amber cards live below the compact vitals; brief status feedback follows the stack. */
  top: calc(max(8px, env(safe-area-inset-top)) + 70px);
  transform: translate(-50%, 0);
}

body[data-experience='phone'] #message {
  /* Amber cards live below the compact vitals; brief status feedback follows the stack. */
  top: calc(max(8px, env(safe-area-inset-top)) + 70px);
  transform: translate(-50%, 0);
}
/* Long reading uses the available width instead of a deep card over the hero. */
body[data-experience='phone'] #message.wide-notice {
  --notice-edge: max(8px, env(safe-area-inset-left), env(safe-area-inset-right));
  width: calc(100vw - 2 * var(--notice-edge));
}
body[data-experience='phone'] #message.wide-notice .notice-card {
  padding: 6px 9px;
  border-radius: 6px;
  overflow-wrap: anywhere;
  line-height: 1.3;
}
body[data-experience='phone'] #message .notice-card.notice-narration::before {
  display: inline;
  margin: 0 6px 0 0;
}
